let S=null,timer=null,S_follow={},VIEW="menu";
function setBar(show,pct){$("prog").classList.toggle("hidden",!show);if(show)$("prog").firstElementChild.style.width=pct+"%";}
function setBottom(html){const b=$("bottom");b.classList.toggle("hidden",!html);b.innerHTML=html||"";}


function renderAside(){
  const a=$("aside");if(!a)return;
  if((VIEW==="q"||VIEW==="essay")&&S&&!S.done&&(S.mode==="study"||S.mode==="mock")&&S.ids.length){
    const cells=S.ids.map((id,i)=>`<button class="cell ${S.ans[i]!==null?"ans":""} ${S.flag&&S.flag[i]?"fl":""} ${VIEW==="q"&&i===S.cur?"cur":""}" data-i="${i}">${i+1}</button>`).join("");
    const done=S.ans.filter(x=>x!==null).length;
    a.innerHTML=`<div class="card"><div class="cap" style="margin-bottom:6px">${S.title}</div>${S.mode==="mock"?`<div class="clock" style="font-size:30px;margin-bottom:4px" id="clock2">${fmt(S.secs)}</div>`:""}<div class="cap">${done} of ${S.ids.length} answered</div><div class="grid" style="margin-top:10px">${cells}${S.mode==="mock"?`<button class="cell" style="grid-column:span 5;aspect-ratio:auto;border-radius:6px;padding:6px;${VIEW==="essay"?"box-shadow:0 0 0 2px var(--paper),0 0 0 4px var(--ink)":""}" id="aEssay">Essay</button>`:""}</div>
      ${P.marks.length?`<div class="cap" style="margin-top:10px">★ ${P.marks.length} bookmarked</div>`:""}
      ${S.mode==="mock"?`<button class="primary" id="aSubmit" style="width:100%;margin-top:10px">Turn in</button>`:""}</div>`;
    a.querySelectorAll(".cell[data-i]").forEach(c=>c.onclick=()=>{S.cur=+c.dataset.i;if(S.mode==="mock")S.onEssay=false;save();renderQ(S.mode==="study");});
    if($("aEssay"))$("aEssay").onclick=showEssay;
    if($("aSubmit"))$("aSubmit").onclick=()=>$("bSubmit")?$("bSubmit").click():showEssay();
  } else if(VIEW==="menu"){
    const seen=Object.keys(P.seen).length;
    a.innerHTML=`<div class="card"><div class="cap">District of Puerto Rico</div><div class="big" style="font-size:34px;margin:4px 0">${daysLeft().replace(" to the exam","")}</div><div class="cap">to the Federal Bar Examination, Oct 24, 2026 · 9:00 a.m.</div></div>
      <div class="card"><h2 style="font-size:17px">Rule books</h2><div class="books">${BOOKS.map(b=>`<a href="${b.u}" target="_blank" rel="noopener">${esc(b.n)} ↗</a>`).join("")}</div></div>`;
  } else if(VIEW==="guide"&&a.dataset.toc){
    a.innerHTML=a.dataset.toc;
  } else {
    a.innerHTML=`<div class="card"><h2 style="font-size:17px">Rule books</h2><div class="books">${BOOKS.map(b=>`<a href="${b.u}" target="_blank" rel="noopener">${esc(b.n)} ↗</a>`).join("")}</div></div>`;
  }
}

