function showTop(){host.classList.remove("onmenu");}
function booksView(){CURVIEW=booksView;VIEW="books";showTop();$("tbTitle").textContent="Rule books";$("clock").classList.add("hidden");setBar(false);setBottom("");S=null;$("content").innerHTML=`<div class="card"><h2>Rule books</h2><p class="cap" style="margin-bottom:12px">The sources behind every question. Every answer also links straight to its rule.</p><div class="books">${BOOKS.map(b=>`<a href="${b.u}" target="_blank" rel="noopener">${esc(b.n)} ↗</a>`).join("")}</div></div>`;renderAside();window.scrollTo({top:0});}
