  CURVIEW=menu;RET=null;
  VIEW="menu";host.classList.add("onmenu");clearInterval(timer);$("clock").classList.add("hidden");$("tbTitle").textContent="FBE Prep";setBar(false);setBottom("");
  const seen=Object.keys(P.seen).length,missed=P.missed.length;
